    function Increment() public returns(uint256) {
        number++;
        emit Incremented(number);
        return number;
    } 
    function Decrement() public returns(uint256) {
        require(number!=0);
        number--;
         emit Decremented(number);
        return number;
    }
    function Reset() external returns(uint256){
               number=0;
         emit Reseted(number);
        return number;
    }

}

